var channel = new Mark1OnNextChannel<RateTableDto>();
var entropy = new RecursiveEntropyCollapse<RateTableDto>(channel);

channel.Subscribe(data => Console.WriteLine($"[Emit] {HexReflector.Reflect(data)} :: {data}"));

